contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        require(true);
        address ownerBefore = c.owner();
        bool reverted;
        try c.owned() { reverted = false; } catch { reverted = true; }
        address ownerAfter = c.owner();
        assert(reverted && ownerAfter == ownerBefore);
    }
    receive() external payable {}
}

