contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOwner) public payable {
        require(newOwner != address(0));
        bool reverted;
        // owner of a fresh C is address(0); only the owner can call transferOwnership.
        // msg.sender here is this test contract, which is never the owner, so the call must revert.
        c.transferOwnership(newOwner);
        assert(false);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public payable {
        // Fresh C has owner = address(0); this test contract is not the owner,
        // so owned() must revert. Wrap in try/catch so the assert is reached.
        bool reverted;
        try c.owned() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // owner getter must still return address(0) since nothing changed it.
        assert(reverted && c.owner() == address(0));
    }
    receive() external payable {}
}

