        // The deciding call must revert and leave ownership unchanged.
        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted && c.owner() == address(0));
    }
    receive() external payable {}
}

